const crypto = require('crypto');
const installationId=Number($env.APROVA_CHAT_INSTALLATION_ID||0);
if(!Number.isSafeInteger(installationId)||installationId<=0||!$env.N8N_SEGREDO_ACOES)throw new Error('Consulta não configurada.');
const entrada=$input.first().json;
const padrao=new Date();padrao.setUTCHours(0,0,0,0);padrao.setUTCDate(padrao.getUTCDate()-(padrao.getUTCDay()+6)%7-7);
function data(nome,deslocamento){
 const valor=entrada[nome]??'';
 if(typeof valor!=='string')throw new Error('Data inválida.');
 let d;if(!valor.trim()){d=new Date(padrao);d.setUTCDate(d.getUTCDate()+deslocamento);}
 else{if(!/^\d{4}-\d{2}-\d{2}$/.test(valor.trim()))throw new Error('Data inválida.');d=new Date(valor.trim()+'T00:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==valor.trim())throw new Error('Data inválida.');}
 return d;
}
const a=data('inicio_a',0),b=data('inicio_b',-7);
if(a.getTime()===b.getTime())throw new Error('Informe duas janelas diferentes.');
const base=($env.APROVA_API_URL||'http://host.docker.internal:8080').replace(/\/+$/,'');
return [a,b].map((d,indice)=>{
 const inicio=d.toISOString().slice(0,10),fim=new Date(d);fim.setUTCDate(fim.getUTCDate()+7);
 const query='installation_id='+installationId+'&inicio='+inicio;
 const timestamp=Math.floor(Date.now()/1000).toString();
 const assinatura='sha256='+crypto.createHmac('sha256',$env.N8N_SEGREDO_ACOES).update(timestamp+'.'+query).digest('hex');
 return {json:{indice,installation_id:installationId,inicio,fim:fim.toISOString().slice(0,10),requisicao:{url:base+'/reports/weekly?'+query,headers:{'X-Aprova-Timestamp':timestamp,'X-Aprova-Assinatura':assinatura}}}};
});

const consulta = $('01 | Preparar Duas Semanas').item.json;

const indisponivel = () => ({
  json: {
    status: 'indisponivel',
    mensagem: 'Não foi possível obter um relatório válido da API.',
    periodo_solicitado: {
      inicio: consulta.inicio,
      fim_exclusivo: consulta.fim,
      fuso: 'UTC',
    },
    dados: null,
  },
});

const r = $json.body ?? $json.data;

if (
  $json.statusCode !== 200 ||
  !r ||
  typeof r !== 'object' ||
  Array.isArray(r)
) {
  return indisponivel();
}

const campos = [
  'total_execucoes',
  'concluidas',
  'rejeitadas',
  'falhas',
  'em_andamento',
  'exigiram_aprovacao_humana',
  'risco_medio',
  'revertidas',
];

if (
  r.installation_id !== consulta.installation_id ||
  r.inicio !== consulta.inicio + 'T00:00:00Z' ||
  r.fim !== consulta.fim + 'T00:00:00Z' ||
  campos.some(c => !Number.isSafeInteger(r[c]) || r[c] < 0)
) {
  return indisponivel();
}

const finalizadas = r.concluidas + r.rejeitadas + r.falhas;

if (
  finalizadas + r.em_andamento !== r.total_execucoes ||
  r.exigiram_aprovacao_humana > r.total_execucoes ||
  r.risco_medio > r.total_execucoes
) {
  return indisponivel();
}

const taxaValida = finalizadas === 0
  ? r.taxa_sucesso === null
  : typeof r.taxa_sucesso === 'number' &&
    Number.isFinite(r.taxa_sucesso) &&
    Math.abs(r.taxa_sucesso - r.concluidas / finalizadas) <= 0.000001;

if (!taxaValida) {
  return indisponivel();
}

return {
  json: {
    status: 'disponivel',
    installation_id: r.installation_id,
    periodo: {
      inicio: r.inicio,
      fim_exclusivo: r.fim,
      fuso: 'UTC',
    },
    dados: {
      ...Object.fromEntries(campos.map(c => [c, r[c]])),
      taxa_sucesso: r.taxa_sucesso,
    },
  },
};

const relatorios=$input.all().map(i=>i.json);
if(relatorios.length!==2||relatorios.some(r=>r.status!=='disponivel'))return [{json:{status:'indisponivel',mensagem:'Não foi possível confirmar as duas semanas; comparação indisponível.',dados:null}}];
const [a,b]=relatorios;
if(a.installation_id!==b.installation_id||a.periodo.inicio===b.periodo.inicio)return [{json:{status:'indisponivel',dados:null}}];
const campos=['total_execucoes','concluidas','rejeitadas','falhas','em_andamento','exigiram_aprovacao_humana','risco_medio','revertidas'];
return [{json:{status:'disponivel',installation_id:a.installation_id,relatorios,
 diferenca_a_menos_b:Object.fromEntries(campos.map(c=>[c,a.dados[c]-b.dados[c]])),
 diferenca_taxa_pontos_percentuais:a.dados.taxa_sucesso===null||b.dados.taxa_sucesso===null?null:100*(a.dados.taxa_sucesso-b.dados.taxa_sucesso),
 observacao:'A diferença é a primeira janela menos a segunda. Taxa nula não é zero. Janelas têm sete dias UTC; semana em curso é parcial. Métricas são da instalação, sem filtro por repositório.'}}];
